const NAME_WORD = /^\p{Lu}[\p{L}'’.-]*\p{Ll}[\p{L}'’.-]*$/u
export function looksLikePerson(name) {
  const words = String(name).trim().split(/\s+/)
  return words.length >= 2 && words.length <= 3 && words.every((word) => NAME_WORD.test(word) && !GROUP_WORDS.has(word.toLowerCase()))
}
const owner = (name, kind) => ((kind ?? (looksLikePerson(name) ? "person" : "group")) === "person" ? person(name) : chip(name))

/** Links rendered as buttons: <p data-slot="actions"> with one <a data-variant> each. The first is primary unless it says otherwise. */
const actions = (list) => (list?.length
  ? h("p", { "data-slot": "actions" }, list.map((action, index) => h("a", { href: action.href, "data-variant": action.kind ?? (index === 0 ? "primary" : "secondary") }, action.label)))
  : null)
/** A value that may be a link. */
const linked = (value, href) => (href ? h("a", { href }, value) : value)

/** Extra attributes on a block's root, beyond data-block and its options. */
const ROOT_ATTRS = {
  section: (d) => ({ "aria-label": d.title }),
  callout: (d) => ({ "aria-label": d.title }),
  "step-list": (d) => ({ "data-count": Math.max(2, Math.min(d.steps.length, 6)) }),
}

const BLOCKS = {
  "page-header": (d, o) => [
    o.eyebrow === "on" && d.eyebrow ? h("p", { "data-slot": "eyebrow" }, d.eyebrow) : null,
    h("h1", null, d.title),
    d.meta?.length ? h("p", { "data-slot": "meta" }, d.meta.map((fact) => h("span", null, fact))) : null,
    actions(d.actions),
  ],

  section: (d, o, ctx, path) => [
    h("h2", null, d.title),
    d.intro ? h("p", null, d.intro) : null,
    (d.blocks ?? []).map((child, index) => renderBlock(child, `${path}.data.blocks[${index}]`, ctx, "section")),
  ],

  "stat-row": (d, o) => d.stats.map((stat) => h("div", null,
    h("span", { "data-slot": "label" }, stat.label),
    h("span", { "data-slot": "value" }, stat.value),
    o.delta !== "none" && stat.delta ? h("span", { "data-slot": "delta", "data-tone": stat.tone }, stat.delta) : null,
  )),

  // The table scrolls inside the block (its card when bordered); a scroll region must be focusable and named (axe).
  "data-table": (d) => h("div", { "data-slot": "scroll", role: "region", tabindex: "0", "aria-label": d.caption ?? "Table" }, h("table", null,
    d.caption ? h("caption", null, d.caption) : null,
    h("thead", null, h("tr", null, d.columns.map((column) => h("th", { scope: "col", "data-numeric": column.numeric === true }, column.label)))),
    h("tbody", null, d.rows.map((row) => h("tr", null, d.columns.map((column) =>
      h("td", { "data-numeric": column.numeric === true }, Object.hasOwn(row, column.key) ? row[column.key] : ""))))),
  )),

  "card-grid": (d) => d.cards.map((card) => h("article", { "data-highlight": card.highlight === true },
    card.tag ? h("span", { "data-slot": "tag" }, card.tag) : null,
    h("h3", null, card.title),
    card.price !== undefined ? h("p", { "data-slot": "price" }, h("strong", null, card.price), card.period ? [" ", h("span", null, card.period)] : null) : null,
    card.body ? h("p", null, card.body) : null,
    card.features?.length ? h("ul", { "data-slot": "features" }, card.features.map((feature) => h("li", null, feature))) : null,
    card.action ? actions([{ kind: "primary", ...card.action }]) : null,
  )),

  record: (d, o) => [
    h("div", { "data-slot": "head" }, h("h3", null, d.title), o.status === "on" && d.status ? chip(d.status.label, d.status.state) : null),
    d.fields?.length ? h("dl", null, d.fields.map((field) => h("div", null, h("dt", null, field.label), h("dd", null, linked(field.value, field.href))))) : null,
  ],

  "decision-list": (d, o) => h("ol", null, d.items.map((item) => h("li", null,
    o.variant === "log" ? h("time", null, item.date ?? "") : null,
    h("strong", null, item.title),
    item.why ? h("p", null, item.why) : null,
  ))),

  "step-list": (d, o) => h("ol", null, d.steps.map((step, index) => {
    const state = step.state ?? "next"
    const vertical = o.orientation === "vertical"
    let marker = null
    if (vertical && o.marker === "time") marker = h("span", { "data-slot": "marker" }, step.time ?? String(index + 1))
    else if (vertical) marker = h("span", { "data-slot": "marker", "aria-hidden": "true" }, o.marker === "check" && state === "done" ? "✓" : String(index + 1))
    return h("li", { "data-state": state, "aria-current": state === "current" ? "step" : null },
      marker,
      step.label ? h("span", { "data-slot": "label" }, step.label) : null,
      h("strong", null, step.title),
      vertical && step.body ? h("p", null, step.body) : null,
    )
  })),

  "action-list": (d, o) => h("ul", null, d.items.map((item) => h("li", { "data-done": item.done === true },
    item.done === true ? h("span", { "data-slot": "box", role: "img", "aria-label": "Done" }, "✓") : h("span", { "data-slot": "box", "aria-hidden": "true" }),
    h("span", { "data-slot": "task" }, item.task),
    o.owner === "on" && item.owner ? owner(item.owner, item.ownerKind) : null,
    o.due === "on" && item.due ? h("span", { "data-slot": "due" }, item.due) : null,
  ))),

  callout: (d) => [
    d.label ? h("span", { "data-slot": "label" }, d.label) : null,
    h("h3", null, d.title),
    d.body ? h("p", null, d.body) : null,
    actions(d.actions),
  ],

  chips: (d, o) => h("ul", null, d.items.map((item) => h("li", null,
    o.kind === "person" ? person(item.label) : chip(item.label, o.kind === "state" ? item.state ?? "neutral" : null),
  ))),

  "page-footer": (d, o) => [
    o.variant === "columns" && d.columns?.length
      ? d.columns.map((column) => h("div", { "data-slot": "column" }, h("span", { "data-slot": "label" }, column.label), h("span", null, linked(column.value, column.href))))
      : null,
    h("span", null, d.note),
    o.live === "on" ? h("span", { "data-slot": "live" }, d.liveText ?? "Live page, always current") : null,
  ],
}

function renderBlock(block, path, ctx, parent) {
  if (parent && isObject(block) && block.block === parent) {
    fail(ctx, `${path}.block`, `a ${parent} can't hold another ${parent}`)
    return null
  }
  const before = ctx.errors.length
  checkBlock(block, path, ctx)
  if (ctx.errors.length > before) return null
  const def = BY_NAME[block.block]
  const data = block.data ?? {}
  const options = {}
  for (const [name, option] of Object.entries(def.options)) options[name] = block.options?.[name] ?? option.default
  try {
    const attrs = { "data-block": def.name }
    for (const [name, value] of Object.entries(options)) attrs[`data-${name}`] = value
    Object.assign(attrs, ROOT_ATTRS[def.name]?.(data, options))
    return h(def.element, attrs, BLOCKS[def.name](data, options, ctx, path))
  } catch (error) {
    fail(ctx, path, `could not render: ${error instanceof Error ? error.message : String(error)}`)
    return null
  }
}

/* ---------- page ---------- */

/** The page axes a view resolves to (defaults for anything missing or invalid). */
export function page(view) {
  const theme = isObject(view) && typeof view.theme === "string" && (REGISTRY.page.theme.values.includes(view.theme) || THEME_PATH.test(view.theme))
    ? view.theme
    : REGISTRY.page.theme.default
  return {
    title: isObject(view) && typeof view.title === "string" ? view.title : "",
    theme,
    density: pageValue(view, "density"),
    shell: pageValue(view, "shell"),
    mode: pageValue(view, "mode"),
  }
}

/* ---------- theme switch (several themes on one page) ---------- */

const THEME_SLUG = /^[a-z0-9][a-z0-9-]*$/

/** options.themes -> [{ slug, label }], or [] when there is nothing to switch between. Throws on a bad slug (a caller error, not a view error). */
function themeList(themes) {
  if (themes === undefined || themes === null) return []
  if (!Array.isArray(themes)) throw new TypeError("options.themes must be a list of { slug, label } or slugs")
  const list = themes.map((theme) => (typeof theme === "string" ? { slug: theme, label: theme } : { slug: theme?.slug, label: theme?.label ?? theme?.slug }))
  for (const { slug } of list) {
    if (typeof slug !== "string" || !THEME_SLUG.test(slug)) throw new TypeError(`theme slug ${JSON.stringify(slug)} must be lowercase ASCII letters, digits and hyphens`)
  }
  return list.length > 1 ? list : []
}

/** The segmented control: hidden until themeSwitch() runs, so a page without JS reads as its first theme. */
const switcher = (themes, initial) => h("div", { "data-slot": "theme-switch", role: "group", "aria-labelledby": "rk-theme-label", hidden: true },
  h("span", { id: "rk-theme-label", "data-slot": "label" }, "Theme"),
  themes.map((theme) => h("button", { type: "button", value: theme.slug, "aria-pressed": theme.slug === initial ? "true" : "false" }, theme.label)),
)

/**
 * themeSwitch(root, win?): wires the theme switch inside a [data-kit] root. The URL hash picks the
 * theme (#paper; anything else means the page's initial theme, the button rendered pressed), each
 * button sets the hash, and hashchange applies it: data-rk-theme on the root, aria-pressed on the
 * buttons. Self-contained on purpose: renderPage() inlines this function's source as the page's only script.
 */
export function themeSwitch(root, win) {
  win = win || globalThis
  var group = root && root.querySelector("[data-slot=\"theme-switch\"]")
  if (!group) return
  var buttons = Array.prototype.slice.call(group.querySelectorAll("button[value]"))
  var slugs = buttons.map(function (button) { return button.value })
  var pressed = buttons.filter(function (button) { return button.getAttribute("aria-pressed") === "true" })[0]
  var initial = pressed ? pressed.value : slugs[0]
  function show() {
    var wanted = win.location.hash.slice(1)
    var slug = slugs.indexOf(wanted) >= 0 ? wanted : initial
    root.setAttribute("data-rk-theme", slug)
    buttons.forEach(function (button) { button.setAttribute("aria-pressed", String(button.value === slug)) })
  }
  buttons.forEach(function (button) {
    button.addEventListener("click", function () { win.location.hash = button.value })
  })
  win.addEventListener("hashchange", show)
  group.hidden = false
  show()
}

function build(view, rootTag, options) {
  const ctx = { errors: [], warnings: [] }
  checkPage(view, ctx)
  const axes = page(view)
  const themes = themeList(options.themes)
  const initial = themes.find((theme) => theme.slug === options.initialTheme)?.slug ?? themes[0]?.slug
  const blocks = isObject(view) && Array.isArray(view.blocks) ? view.blocks : []
  const children = []
  // topbar shell: the first <header> of the [data-kit] root is the sticky bar (kit.css); the theme switch sits in it.
  if (axes.shell === "topbar") children.push(h("header", null, h("a", { href: "#main" }, axes.title.split(" · ")[0] || "Home"), themes.length ? switcher(themes, initial) : null))
  else if (themes.length) children.push(switcher(themes, initial))
  children.push(h("main", { id: "main" }, blocks.map((block, index) => renderBlock(block, `blocks[${index}]`, ctx))))
  const root = h(rootTag, {
    "data-kit": true,
    "data-shell": axes.shell,
    "data-density": axes.density,
    "data-rk-theme": themes.length ? initial : null,
    "data-outline": options.outline === true,
  }, children)
  return { root, axes, themes, errors: ctx.errors, warnings: ctx.warnings }
}

/**
 * render(view, { document?, outline? }) -> { node, html, errors, warnings }
 * `node` is a <div data-kit data-shell data-density> holding the page (null without a DOM);
 * `html` is the same element as a string. Mode lives on <html> (kit.css), so put data-mode there
 * yourself, or use mount() / renderPage(), which do it for you.
 */
export function render(view, options = {}) {
  const built = build(view, "div", options)
  const doc = options.document ?? globalThis.document
  return { node: doc ? toDom(doc, built.root) : null, html: toHtml(built.root), errors: built.errors, warnings: built.warnings }
}

/** renderToString(view, { outline? }) -> { html, errors, warnings }. No DOM needed (Node, CLI, pre-rendering). */
export function renderToString(view, options = {}) {
  const built = build(view, "div", options)
  return { html: toHtml(built.root), errors: built.errors, warnings: built.warnings }
}

/** validate(view) -> { errors, warnings }: the renderer's own checks, nothing rendered. */
export function validate(view) {
  const { errors, warnings } = build(view, "div", {})
  return { errors, warnings }
}

/**
 * mount(view, { document?, target?, outline? }) -> { node, errors, warnings }
 * Renders into `target` (default document.body): sets data-kit / data-shell / data-density on it,
 * data-mode on <html> and document.title, and replaces its children. For Artifacts and live pages.
 */
export function mount(view, options = {}) {
  const doc = options.document ?? options.target?.ownerDocument ?? globalThis.document
  const built = build(view, "body", options)
  const target = options.target ?? doc.body
  for (const [name, value] of Object.entries(built.root.attrs)) target.setAttribute(name, value)
  target.replaceChildren(...built.root.children.map((child) => toDom(doc, child)))
  doc.documentElement.setAttribute("data-mode", built.axes.mode)
  if (built.axes.title) doc.title = built.axes.title
  if (built.themes.length) themeSwitch(target, doc.defaultView)
  return { node: target, errors: built.errors, warnings: built.warnings }
}

/**
 * renderPage(view, { styles?, fonts?, host?, themes?, lang?, outline? }) -> { html, errors, warnings }
 *
 * host "static" (default): a whole document: <html data-mode>, <title>, the fonts stylesheet, the
 * styles in order, <body data-kit …>. `styles` is a list of { href } (linked) or { css } (inlined);
 * pass the theme vars, kit.css and blocks.css, in that order. `rebel-kit render` builds it for you.
 *
 * host "artifact": the body of a claude.ai Artifact, which the platform wraps in its own doctype,
 * <html>, <head> and <body>. So: <title>, the viewport-fit-sides meta, the fonts stylesheet, one
 * <style> with every style inlined (only { css } styles; CSS comments dropped), then <div data-kit …>. Mode is CSS here
 * (the theme tokens; see hosts.ts), not data-mode.
 *
 * `fonts` is a stylesheet URL (Google Fonts), the only thing either page loads besides its styles.
 * `themes` (two or more [{ slug, label }]) adds the theme switch and its inline script, and puts
 * data-rk-theme="<slug>" on the root: `initialTheme` when it is one of them, else the first. The
 * styles must scope each theme by that attribute.
 */
export function renderPage(view, options = {}) {
  const host = options.host ?? "static"
  if (host !== "static" && host !== "artifact") throw new TypeError(`host must be "static" or "artifact", not ${JSON.stringify(host)}`)
  const artifact = host === "artifact"
  const built = build(view, artifact ? "div" : "body", options)
  const styles = options.styles ?? []
  const fonts = typeof options.fonts === "string" && options.fonts ? [`<link rel="stylesheet" href="${escapeAttr(options.fonts)}">`] : []
  // The end tag is split so this file stays pasteable into an inline <script type="module">: a literal one would close it here.
  const script = built.themes.length
    ? `<script>(${themeSwitch.toString()})(document.querySelector("[data-kit][data-rk-theme]"), window)</${"script"}>`
    : ""
  const title = `<title>${escapeText(built.axes.title)}</title>`

  if (artifact) {
    if (styles.some((style) => typeof style.css !== "string")) throw new TypeError("an Artifact inlines every style: pass { css }, not { href }")
    // Comments go: they are bytes the viewer downloads, and kit's mention <html> / <body>, which the file must not contain.
    const css = styles.map((style) => style.css.replace(/\/\*[\s\S]*?\*\//g, "").replace(/\n\s*\n+/g, "\n").trim())
      .join("\n").replace(/<\/style/gi, "<\\/style")
    const html = [
      title,
      "<meta name=\"claude:viewport-fit-sides\" content=\"cover\">",
      ...fonts,
      `<style>\n${css}\n</style>`,
      toHtml(built.root) + script,
      "",
    ].join("\n")
    return { html, errors: built.errors, warnings: built.warnings }
  }

  const sheets = styles.map((style) => (typeof style.css === "string"
    ? `<style>\n${style.css.replace(/<\/style/gi, "<\\/style")}\n</style>`
    : `<link rel="stylesheet" href="${escapeAttr(String(style.href))}">`))
  const html = [
    "<!doctype html>",
    `<html lang="${escapeAttr(options.lang ?? "en")}" data-mode="${built.axes.mode}">`,
    "<head>",
    "<meta charset=\"utf-8\">",
    "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">",
    title,
    ...fonts,
    ...sheets,
    "</head>",
    toHtml(built.root).replace(/<\/body>$/, `${script}</body>`),
    "</html>",
    "",
  ].join("\n")
  return { html, errors: built.errors, warnings: built.warnings }
}

export const RebelKit = { registry, page, render, renderToString, renderPage, mount, validate, themeSwitch, looksLikePerson, COLOR_PATTERN, HREF_PATTERN }
globalThis.RebelKit = RebelKit
